import React, { useState } from "react";
import WidgetForm from "./widget_form.jsx";

import { Card, CardContent, Typography, Button } from "@mui/material";
import { URL } from "url";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faArrowLeft } from "@fortawesome/free-solid-svg-icons";

function Content(props) {
  const {
    datos,
    setDatos,
    contenedorRef,
    sumDispRef,
    volver,
    dispositivos,
    setDispositivos,
    dashboard_id,
    user
  } = props;
  const [selectedWidget, setSelectedWidget] = useState(null);
  const [hasScriptFields, setHasScriptFields] = useState(false);



  const handleWidgetClick = (widgetType) => {
    setSelectedWidget(widgetType);
  };
  const handleWidgetCancel = () => {
    setSelectedWidget(null);
  };

  const renderWidgetForm = () => {
    return (
      <WidgetForm
        datos={datos}
        setDatos={setDatos}
        dispositivos={dispositivos}
        setDispositivos={setDispositivos}
        dashboard_id={dashboard_id}
        widgetType={selectedWidget}
        user={user}
        onHasScriptFields={setHasScriptFields} // Pasar callback al hijo
      />
    );
  };

  const deviceTypes = [
    {
      id: 1,
      name: "switch",
      image:
        "data:image/png;base64,",
    },
    {
      id: 2,
      name: "lineChart",
      image:
        "data:image/png;base64,",
    },
    {
      id: 3,
      name: "barChart",
      image:
        "data:image/png;base64,",
    },
    {
      id: 3,
      name: "map",
      image:
        "data:image/png;base64,",
    },
    {
      id: 4,
      name: "customValueCard",
      image:
        "data:image/png;base64,",
    },
  ];

  return (
    <div className="min-w-fit min-h-full w-fit h-full bg-white border border-gray-300 rounded p-2.5 shadow-lg m-auto overflow-hidden">
      {!selectedWidget ? (
        <>
          <div className="flex justify-between items-center py-2 w-full">
            <button
              onClick={() => volver()}
              className="w-12 h-10 ml-10 flex items-center justify-center rounded-full bg-white hover:bg-gray-200 focus:outline-none focus:ring-2 focus:ring-indigo-400 transition-colors duration-200"
            >
              <FontAwesomeIcon icon={faArrowLeft} />
            </button>
            <div className="flex justify-center items-center py-2 w-full">
              <h2 className="font-medium text-gray-900 text-xl pr-10">
                Crear Widget
              </h2>
            </div>
          </div>
          <div className="panelDeWidgets flex flex-wrap gap-4 justify-center">
            {deviceTypes.map((device) => (
              <Card
                key={device.id}
                className="max-w-[200px] min-w-[150px] w-full"
              >
                <CardContent>
                  <img
                    src={device.image}
                    alt={device.name}
                    className="max-w-full h-auto"
                  />
                  <Typography variant="h6" className="mt-2">
                    {device.name}
                  </Typography>
                  <Button
                    variant="contained"
                    color="primary"
                    onClick={() => handleWidgetClick(device.name)}
                    className="mt-2"
                  >
                    Ver detalles
                  </Button>
                </CardContent>
              </Card>
            ))}
          </div>
        </>
      ) : (
        <div className="w-full flex flex-col items-center">
          <div className="panelDeForms flex flex-col items-center w-full">
            <div className="flex justify-between items-center py-2 w-full">
              <button
                onClick={() => handleWidgetCancel()}
                className="w-12 h-10 ml-5 flex items-center justify-center rounded-full bg-white hover:bg-gray-200 focus:outline-none focus:ring-2 focus:ring-indigo-400 transition-colors duration-200"
              >
                <FontAwesomeIcon icon={faArrowLeft} />
              </button>
              <div className="flex justify-center items-center py-2 w-full">
                <h2 className="font-medium text-gray-900 text-xl pr-10">
                  Crear Widget
                </h2>
              </div>
            </div>
            <div className={`max-w-full ${
              hasScriptFields ? "lg:max-w-[1000px]" : "lg:max-w-[500px]"
            } w-full]`}>
              {renderWidgetForm()}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Content;
